root <- normalizePath(".",mustWork=TRUE); path <- file.path(root,"outputs/preprocessing_demo/model_inputs.rds"); if (!file.exists(path)) stop("Run scripts/run_preprocessing_demo.R first"); x <- readRDS(path); stopifnot(all(c("tier1","tier2","prediction_grid","time_index","transformations","provenance") %in% names(x))); stopifnot(!anyDuplicated(x$time_index$time_index)); stopifnot(!anyDuplicated(x$prediction_grid$space_time_id)); stopifnot(length(unique(x$prediction_grid$cell_id))*nrow(x$time_index)==nrow(x$prediction_grid)); message("Preprocessing demo smoke checks passed")
